CREATE TABLE IF NOT EXISTS m_inventory (
    id INT PRIMARY KEY,
    barcode VARCHAR(100),
    inventory_no VARCHAR(100),
    inventory_name VARCHAR(255),
    inventory_brand_id INT,
    inventory_category_id INT,
    inventory_product_id INT,
    uom_id INT,
    min_stock INT,
    max_stock INT,
    kode_harga VARCHAR(255),
    description TEXT,
    price NUMERIC(18,2),
    disc NUMERIC(18,2),
    is_active BOOLEAN,
    hpp NUMERIC(18,2),
    price_buy NUMERIC(18,2),
    grosir1 NUMERIC(18,2),
    grosir2 NUMERIC(18,2),
    grosir3 NUMERIC(18,2),
    stok_awal INT,
    stok_update INT
);
TRUNCATE TABLE m_inventory;
